+  <main class="page-shell">
+    <section class="preview-layout" aria-label="Image preview">
+      <article class="card preview-card">
+        <figure class="image-frame">
+          <img
+            src="https://images.unsplash.com/photo-1511300636408-a63a89df3482?auto=format&fit=crop&w=1200&q=80"
+            alt="Warm sunset light over a calm lake with trees in the distance"
+          >
+        </figure>
+
+        <div class="actions">
+          <div class="image-meta">
+            <p class="eyebrow">Library preview</p>
+            <h1>Golden hour by the lake</h1>
+            <p class="description">Review your saved image before sharing, organizing, or removing it from your personal library.</p>
+          </div>
+
+          <button type="button" class="trigger" id="open-dialog">
+            Delete image
+          </button>
+        </div>
+      </article>
+
+      <aside class="card details-card" aria-label="Image details">
+        <div>
+          <p class="eyebrow">Overview</p>
+          <h2>Asset details</h2>
+        </div>
+
+        <ul class="meta-list">
+          <li>
+            <strong>Collection</strong>
+            Nature inspiration
+          </li>
+          <li>
+            <strong>Resolution</strong>
+            3840 x 2880 px
+          </li>
+          <li>
+            <strong>Added</strong>
+            May 4, 2026
+          </li>
+        </ul>
+
+        <div class="button-row">
+          <button type="button" class="primary">Download</button>
+          <button type="button" class="secondary">Share</button>
+        </div>
+
+        <p class="description">Deleting this image removes it from your library. You can review that action in the confirmation dialog before anything changes.</p>
+        <p class="status" id="status-message" aria-live="polite"></p>
+      </aside>
+    </section>
+  </main>
+
+  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
+    <div class="dialog-panel">
+      <div class="dialog-icon" aria-hidden="true">!</div>
+      <h2 id="dialog-title">Delete this image?</h2>
+      <p class="dialog-copy" id="dialog-description">
+        This will remove <strong>Golden hour by the lake</strong> from your library. This action cannot be undone.
+      </p>
+
+      <form method="dialog" class="dialog-actions">
+        <button type="button" class="secondary" id="cancel-dialog">Cancel</button>
+        <button type="button" class="danger" id="confirm-delete">Yes, delete</button>
+      </form>
+    </div>
+  </dialog>
+
+  <script>
+    const trigger = document.querySelector(".trigger");
+    const dialog = document.getElementById("delete-dialog");
+    const cancelButton = document.getElementById("cancel-dialog");
+    const confirmButton = document.getElementById("confirm-delete");
+    const statusMessage = document.getElementById("status-message");
+
+    trigger.addEventListener("click", () => {
+      dialog.showModal();
+    });
+
+    cancelButton.addEventListener("click", () => {
+      dialog.close();
+    });
+
+    confirmButton.addEventListener("click", () => {
+      dialog.close();
+      statusMessage.textContent = "Image deleted from your library.";
+    });
+
+    dialog.addEventListener("close", () => {
+      if (document.activeElement !== trigger) {
+        trigger.focus();
+      }
+    });
+  </script>
+</body>
+</html>
